#include <vector>
#include <set>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long minimumCost(std::vector<int>& nums, int k, int dist) {
        k--;
        std::multiset<int> left, right;
        long long cur_sum = 0;
        int n = nums.size();
        for (int i = 1; i <= std::min(dist + 1, n - 1); ++i) {
            left.insert(nums[i]);
            cur_sum += nums[i];
        }
        while (left.size() > (size_t)k) {
            auto it = std::prev(left.end());
            cur_sum -= *it;
            right.insert(*it);
            left.erase(it);
        }
        long long ans = cur_sum;
        for (int i = dist + 2; i < n; ++i) {
            int out_val = nums[i - dist - 1];
            auto it = left.find(out_val);
            if (it != left.end()) {
                cur_sum -= *it;
                left.erase(it);
            } else {
                right.erase(right.find(out_val));
            }
            int in_val = nums[i];
            if (!left.empty() && in_val < *std::prev(left.end())) {
                left.insert(in_val);
                cur_sum += in_val;
            } else {
                right.insert(in_val);
            }
            while (left.size() < (size_t)k) {
                auto rit = right.begin();
                cur_sum += *rit;
                left.insert(*rit);
                right.erase(rit);
            }
            while (left.size() > (size_t)k) {
                auto lit = std::prev(left.end());
                cur_sum -= *lit;
                right.insert(*lit);
                left.erase(lit);
            }
            ans = std::min(ans, cur_sum);
        }
        return (long long)nums[0] + ans;
    }
};

import java.util.TreeMap;

class Solution {
    private TreeMap<Integer, Integer> left = new TreeMap<>();
    private TreeMap<Integer, Integer> right = new TreeMap<>();
    private int leftSize = 0, rightSize = 0;
    private long sum = 0;

    private void add(TreeMap<Integer, Integer> map, int val) {
        map.put(val, map.getOrDefault(val, 0) + 1);
    }

    private void remove(TreeMap<Integer, Integer> map, int val) {
        int count = map.get(val);
        if (count == 1) map.remove(val);
        else map.put(val, count - 1);
    }

    public long minimumCost(int[] nums, int k, int dist) {
        k--;
        int n = nums.length;
        for (int i = 1; i <= Math.min(dist + 1, n - 1); ++i) {
            add(left, nums[i]);
            sum += nums[i];
            leftSize++;
        }
        while (leftSize > k) {
            int val = left.lastKey();
            remove(left, val);
            sum -= val;
            leftSize--;
            add(right, val);
            rightSize++;
        }
        long ans = sum;
        for (int i = dist + 2; i < n; ++i) {
            int out = nums[i - dist - 1];
            if (left.containsKey(out)) {
                remove(left, out);
                sum -= out;
                leftSize--;
            } else {
                remove(right, out);
                rightSize--;
            }
            int inVal = nums[i];
            if (!left.isEmpty() && inVal < left.lastKey()) {
                add(left, inVal);
                sum += inVal;
                leftSize++;
            } else {
                add(right, inVal);
                rightSize++;
            }
            while (leftSize < k) {
                int val = right.firstKey();
                remove(right, val);
                rightSize--;
                add(left, val);
                sum += val;
                leftSize++;
            }
            while (leftSize > k) {
                int val = left.lastKey();
                remove(left, val);
                sum -= val;
                leftSize--;
                add(right, val);
                rightSize++;
            }
            ans = Math.min(ans, sum);
        }
        return nums[0] + ans;
    }
}

var minimumCost = function(nums, k, dist) {
    k--;
    const window = nums.slice(1, dist + 2).sort((a, b) => a - b);
    let curSum = 0;
    for (let j = 0; j < k; ++j) curSum += window[j];
    let ans = curSum;
    for (let i = dist + 2; i < nums.length; ++i) {
        const outVal = nums[i - dist - 1];
        const idx = window.indexOf(outVal);
        window.splice(idx, 1);
        const inVal = nums[i];
        let pos = 0;
        while (pos < window.length && window[pos] < inVal) pos++;
        window.splice(pos, 0, inVal);
        let s = 0;
        for (let j = 0; j < k; ++j) s += window[j];
        ans = Math.min(ans, s);
    }
    return nums[0] + ans;
};
